// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * HashStore — append-only on-chain fingerprint registry for AiCoinTrack.
 *
 * Every financial transaction recorded in the MySQL DB gets a keccak256
 * fingerprint of its canonical JSON stored here. This makes the off-chain
 * record tamper-evident: any mutation changes the hash and the mismatch
 * is immediately detectable.
 *
 * userId  = the integer primary key from the MySQL users table
 * txId    = the integer primary key from the MySQL transactions table
 * hash    = keccak256(JSON.stringify(txData, sortedKeys))
 */
contract HashStore {
    // userId → all hashes ever stored for that user (ordered by insertion)
    mapping(uint256 => bytes32[]) public transactionHashes;

    // txId → hash → stored? (O(1) existence check without iterating the array)
    mapping(uint256 => mapping(bytes32 => bool)) public hashExists;

    // txId → hash → block timestamp when it was stored
    mapping(uint256 => mapping(bytes32 => uint256)) public storedAt;

    event HashStored(
        uint256 indexed userId,
        uint256 indexed txId,
        bytes32 hash,
        uint256 timestamp
    );

    /**
     * Store a single fingerprint.
     * Reverts if the exact (txId, hash) pair was already stored
     * to prevent accidental double-writes.
     */
    function storeHash(
        uint256 userId,
        uint256 txId,
        bytes32 hash
    ) external {
        require(!hashExists[txId][hash], "HashStore: already stored");
        transactionHashes[userId].push(hash);
        hashExists[txId][hash] = true;
        storedAt[txId][hash] = block.timestamp;
        emit HashStored(userId, txId, hash, block.timestamp);
    }

    /**
     * Store multiple fingerprints in one transaction (gas-efficient batching).
     * Silently skips duplicates so the batch never reverts mid-way.
     */
    function storeBatch(
        uint256 userId,
        uint256[] calldata txIds,
        bytes32[] calldata hashes
    ) external {
        require(txIds.length == hashes.length, "HashStore: length mismatch");
        for (uint256 i = 0; i < hashes.length; i++) {
            if (!hashExists[txIds[i]][hashes[i]]) {
                transactionHashes[userId].push(hashes[i]);
                hashExists[txIds[i]][hashes[i]] = true;
                storedAt[txIds[i]][hashes[i]] = block.timestamp;
                emit HashStored(userId, txIds[i], hashes[i], block.timestamp);
            }
        }
    }

    /**
     * Return all hashes stored for a user (for audit / frontend display).
     */
    function getHashes(uint256 userId)
        external view returns (bytes32[] memory)
    {
        return transactionHashes[userId];
    }

    /**
     * Check whether a specific (txId, hash) pair was stored.
     * Used by the frontend and backend to verify record integrity.
     */
    function verifyHash(uint256 txId, bytes32 hash)
        external view returns (bool)
    {
        return hashExists[txId][hash];
    }

    /**
     * Return the block timestamp when a hash was stored (0 if not found).
     */
    function getStoredAt(uint256 txId, bytes32 hash)
        external view returns (uint256)
    {
        return storedAt[txId][hash];
    }
}

